package exercise

import (
	"testing"
	"time"
)

type wedge struct{ u, v, w int }

func buildUndirected(n int, edges []wedge) [][]Edge {
	adj := make([][]Edge, n)
	for _, e := range edges {
		adj[e.u] = append(adj[e.u], Edge{To: e.v, Weight: e.w})
		adj[e.v] = append(adj[e.v], Edge{To: e.u, Weight: e.w})
	}
	return adj
}

func TestCheapestNetworkCostSmallGraphs(t *testing.T) {
	cases := []struct {
		name  string
		n     int
		edges []wedge
		want  int
	}{
		{
			name:  "five-vertex example",
			n:     5,
			edges: []wedge{{0, 1, 4}, {0, 2, 8}, {1, 2, 3}, {1, 4, 6}, {2, 3, 2}, {3, 4, 10}},
			want:  15,
		},
		{
			name:  "edge weight matters, not distance from the start",
			n:     3,
			edges: []wedge{{0, 1, 2}, {1, 2, 2}, {0, 2, 3}},
			want:  4,
		},
		{
			name:  "square with diagonals",
			n:     4,
			edges: []wedge{{0, 1, 1}, {1, 2, 4}, {2, 3, 1}, {3, 0, 4}, {0, 2, 2}, {1, 3, 5}},
			want:  4,
		},
		{
			name:  "a cheaper edge to a waiting vertex shows up later",
			n:     4,
			edges: []wedge{{0, 1, 1}, {0, 2, 7}, {1, 3, 2}, {3, 2, 1}},
			want:  4,
		},
		{
			name:  "an expensive bridge must be kept",
			n:     3,
			edges: []wedge{{0, 1, 1}, {1, 2, 100}},
			want:  101,
		},
		{
			name:  "parallel edges keep the cheapest",
			n:     2,
			edges: []wedge{{0, 1, 9}, {0, 1, 2}, {0, 1, 5}},
			want:  2,
		},
		{
			name:  "zero-weight edges",
			n:     3,
			edges: []wedge{{0, 1, 0}, {1, 2, 0}, {0, 2, 4}},
			want:  0,
		},
		{
			name:  "disconnected graph",
			n:     5,
			edges: []wedge{{0, 1, 3}, {3, 4, 1}},
			want:  -1,
		},
		{
			name: "two vertices and no edges",
			n:    2,
			want: -1,
		},
		{
			name: "single vertex",
			n:    1,
			want: 0,
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := CheapestNetworkCost(c.n, buildUndirected(c.n, c.edges))
			if got != c.want {
				t.Errorf("got %d, want %d", got, c.want)
			}
		})
	}
}

func TestCheapestNetworkCostHandlesLargeGraph(t *testing.T) {
	// A long path whose edges cost 1, 2 or 3, where every vertex also has a
	// shortcut two ahead costing 5. Each shortcut is the most expensive edge
	// of its triangle, so the tree is exactly the path. Scanning every vertex
	// for the cheapest one to attach on each step would take tens of billions
	// of comparisons here; a priority queue takes a few million.
	const n = 200000
	edges := make([]wedge, 0, 2*n)
	want := 0
	for u := 0; u+1 < n; u++ {
		w := 1 + u%3
		edges = append(edges, wedge{u, u + 1, w})
		want += w
	}
	for u := 0; u+2 < n; u++ {
		edges = append(edges, wedge{u, u + 2, 5})
	}
	adj := buildUndirected(n, edges)

	const budget = 2 * time.Second
	start := time.Now()
	got := CheapestNetworkCost(n, adj)
	elapsed := time.Since(start)

	if got != want {
		t.Fatalf("got %d, want %d", got, want)
	}
	if elapsed > budget {
		t.Fatalf("took %v on a graph of %d vertices and %d edges, over the %v budget: always take the cheapest vertex to attach from a priority queue instead of scanning every vertex for it", elapsed, n, len(edges), budget)
	}
}

