package exercise

import "container/heap"

type Edge struct {
	To     int
	Weight int
}

type item struct {
	vertex int
	weight int
}

type minHeap []item

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i].weight < h[j].weight }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(item)) }
func (h *minHeap) Pop() any {
	old := *h
	last := old[len(old)-1]
	*h = old[:len(old)-1]
	return last
}

func CheapestNetworkCost(n int, adj [][]Edge) int {
	inTree := make([]bool, n)
	total, count := 0, 0

	h := &minHeap{{vertex: 0, weight: 0}}
	for h.Len() > 0 && count < n {
		cur := heap.Pop(h).(item)
		if inTree[cur.vertex] {
			continue
		}
		inTree[cur.vertex] = true
		total += cur.weight
		count++
		for _, e := range adj[cur.vertex] {
			if !inTree[e.To] {
				heap.Push(h, item{vertex: e.To, weight: e.Weight})
			}
		}
	}

	if count < n {
		return -1
	}
	return total
}
